Method.Source:
protected void init()
{
    api = XAPI_APIS::CreateCustomer;
    super();
}

protected str body()
{
    DimensionAttribute        da;
    DimensionAttributeValue   dv;

    select firstonly name from da
    order by da.Name asc
    join DisplayValue from dv
    where dv.DimensionAttribute == da.RecId;

    Map configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());
    configMap.insert('<AlternativeCustomerNumber>', XAPI_AlternativeCustomerNumberGenerator::generateCPR());
    configMap.insert('<DimensionName>', da.Name);
    configMap.insert('<DimensionValue>', dv.DisplayValue);

    return this.prepareBody(configMap);
}
